import os
import json
import base64
import requests


def extract_receipt_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Missing OpenAI API key. Set OPENAI_API_KEY or pass config['api_key'].")

    model = config.get("model", "gpt-4.1-mini")

    if isinstance(payload, (bytes, bytearray)):
        receipt_data = base64.b64encode(payload).decode("utf-8")
        content = [
            {
                "type": "input_text",
                "text": (
                    "Extract structured receipt data as JSON with keys: merchant, tax, total, items. "
                    "Items should be an array of objects with name, quantity, unit_price, total_price when available. "
                    "Return only valid JSON."
                ),
            },
            {
                "type": "input_image",
                "image_url": f"data:image/png;base64,{receipt_data}",
            },
        ]
    else:
        content = [
            {
                "type": "input_text",
                "text": (
                    "Extract structured receipt data as JSON with keys: merchant, tax, total, items. "
                    "Items should be an array of objects with name, quantity, unit_price, total_price when available. "
                    f"Receipt text:\n{payload}\n\nReturn only valid JSON."
                ),
            }
        ]

    body = {
        "model": model,
        "input": [
            {
                "role": "user",
                "content": content,
            }
        ],
        "temperature": 0,
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers=headers,
        data=json.dumps(body),
        timeout=config.get("timeout", 60),
    )
    response.raise_for_status()
    data = response.json()

    text = ""
    if isinstance(data, dict):
        for item in data.get("output", []):
            for c in item.get("content", []):
                if c.get("type") in ("output_text", "text"):
                    text += c.get("text", "")
        if not text and "output_text" in data:
            text = data["output_text"]

    text = text.strip()
    if text.startswith("```"):
        text = text.strip("`")
        if text.lower().startswith("json"):
            text = text[4:].strip()

    result = json.loads(text)
    return result
